import json,sys,base64,re
def b64(s):
    s=s.replace('-','+').replace('_','/'); s+='='*(-len(s)%4)
    return base64.b64decode(s).decode('utf-8','replace')
def walk(p,out):
    mt=p.get('mimeType','')
    d=(p.get('body') or {}).get('data')
    if d and mt.startswith('text/plain'): out.append(b64(d))
    for q in p.get('parts') or []: walk(q,out)
    if not out and d and mt.startswith('text/html'):
        out.append(re.sub(r'<[^>]+>',' ',b64(d)))
def show(t):
    msgs=t.get('messages',[t] if 'payload' in t else [])
    for m in msgs:
        h={x['name'].lower():x['value'] for x in m['payload'].get('headers',[])}
        print('=== MSG',m.get('id'))
        for k in ['date','from','to','cc','subject']:
            if k in h: print(k.upper()+':',h[k])
        out=[]; walk(m['payload'],out)
        if not out:
            # html fallback
            def wh(p):
                d=(p.get('body') or {}).get('data')
                if d and 'html' in p.get('mimeType',''): out.append(re.sub(r'\s+',' ',re.sub(r'<[^>]+>',' ',b64(d))))
                for q in p.get('parts') or []: wh(q)
            wh(m['payload'])
        body='\n'.join(out)
        # strip quoted replies
        lines=[]
        for l in body.splitlines():
            if re.match(r'^On .* wrote:\s*$',l) or l.startswith('>'): break
            lines.append(l)
        txt='\n'.join(lines).strip()
        txt=re.sub(r'\n\s*\n+','\n',txt)
        print(txt[:3000])
for f in sys.argv[1:]:
    raw=json.load(open(f))
    if isinstance(raw,dict) and 'result' in raw: raw=raw['result']
    if isinstance(raw,str): raw=json.loads(raw)
    show(raw)
EOF
